import { loadFont } from "@remotion/google-fonts/Inter";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// Ensaio de aniversário com IA (marca a confirmar). Motion vertical de 25,8 s no "padrão premium estilo Apple" que o
// cliente pediu: preto na abertura e na vitrine, cinza-claro no resto, Inter apertada, cartões brancos de canto
// redondo, texto que entra desfocado e assenta. Rosé dourado (o tom dos balões das fotos) só no destaque de cada cena.
// Limpo: fundo liso, o texto entra e fica parado; o movimento contínuo fica nos cartões, nas fotos e nos botões.
// Locução (ElevenLabs, 22,4 s) entra em 0,15 s; depois de "Olha a diferença!" há 2 s de pausa para a vitrine das
// fotos, uma por batida da trilha (120 BPM). Tempos = palavra + 0,15 s (+2 s a partir de "Seu aniversário merece").
// Ainda sem logo, sem número de WhatsApp e sem as fotos de "antes": a prova é a vitrine dos ensaios prontos.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const ENS_FPS = 30;
// Versão 2: voz nova (Roberta, 23,9 s sem o silêncio morto). As cenas seguem escritas no tempo da voz antiga; WARP
// converte o tempo do vídeo para esse tempo, palavra por palavra: [tempo no vídeo, tempo antigo]. A vitrine (16,5–19 s)
// passa sem esticar, para cada foto continuar caindo numa batida da trilha.
const WARP: [number, number][] = [[0,0],[0.33,0.28],[0.49,0.4],[1.01,0.96],[1.23,1.08],[2.21,1.94],[2.31,2.25],[2.53,2.52],[2.89,2.83],[3.09,3.03],[3.37,3.31],[3.73,3.69],[3.85,3.79],[4.01,3.93],[4.53,4.37],[4.65,4.49],[5.54,5.47],[5.86,5.77],[6.24,6.11],[6.44,6.27],[6.72,6.53],[6.82,6.61],[7.28,7.05],[7.38,7.11],[7.72,7.43],[8.72,8.39],[8.88,8.56],[9.28,8.92],[9.66,9.3],[10.22,9.78],[10.3,9.84],[10.56,10.1],[10.8,10.3],[10.88,10.38],[11.32,10.72],[11.4,10.8],[12.04,11.48],[13.01,12.34],[13.21,12.54],[13.51,13.0],[14.07,13.54],[14.33,13.77],[15.13,14.59],[15.33,14.75],[15.41,14.81],[16.4,15.4],[19.0,18.0],[19.15,18.15],[19.95,18.85],[20.43,19.37],[20.53,19.43],[20.89,19.77],[21.63,20.31],[21.85,20.53],[21.93,20.59],[22.19,20.83],[22.27,20.89],[23.16,21.65],[23.7,22.12],[23.96,22.34],[24.22,22.6],[24.76,23.06],[25.04,23.28],[25.2,23.42],[25.5,23.68],[26.44,24.54],[27.7,25.8]];
export const ENS_FRAMES = Math.round(WARP[WARP.length - 1][0] * ENS_FPS);
const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.4));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);

const BLACK = "#000000";
const LIGHT = "#F5F5F7";
const INK = "#1D1D1F";
const GRAY = "#86868B";
const CARD_D = "#1C1C1E";
const WA = "#25D366";
const ROSE_D = "linear-gradient(92deg, #F6D2B0 0%, #EBA98C 50%, #E08FA6 100%)";    // sobre preto
const ROSE_L = "linear-gradient(92deg, #C9895C 0%, #C96F6A 55%, #BF557C 100%)";    // sobre claro
const SHADOW = "0 30px 70px rgba(0,0,0,0.10), 0 4px 14px rgba(0,0,0,0.05)";

// tempos das cenas (segundos de vídeo)
const T2 = 5.25, T3 = 8.25, T4 = 14.4, T5 = 18.0;
const SHOW0 = 15.5, BEAT = 0.5;

const PH: Record<string, [number, number]> = { p02: [848, 1256], p03: [800, 1309], p04: [768, 1365], p05: [896, 1197], p06: [800, 1325], p07: [896, 1196], p09: [992, 1078], p10: [1024, 1024], p11: [704, 936], p12: [976, 1103], p13: [688, 1193] };
const ar = (id: string) => PH[id][0] / PH[id][1];

// texto: entra desfocado, assenta e fica parado; sai desfocando
const blurIn = (t: number, at: number, out?: number, d = 0.5): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.22);
  return {
    opacity: Math.min(1, e * 1.6) * (1 - o),
    filter: `blur(${((1 - e) * 22 + o * 16).toFixed(1)}px)`,
    transform: `translateY(${((1 - e) * 34 - o * 18).toFixed(1)}px)`,
  };
};
const grad = (g: string): React.CSSProperties => ({ backgroundImage: g, WebkitBackgroundClip: "text", backgroundClip: "text", color: "transparent" });

type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color: string; accent: string; out?: number }> = ({ t, items, size, top, color, accent, out }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center" }}>
    {items.map(([w, at, hl], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: 600, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.035em", whiteSpace: "nowrap", color, paddingBottom: size * 0.06, ...(hl ? grad(accent) : {}), ...blurIn(t, at, out) }}>
        {w}
      </div>
    ))}
  </div>
);

// ───────── ícones ─────────
const IcoImage: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill="none" stroke={c} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round">
    <rect x={6} y={9} width={36} height={30} rx={6} />
    <circle cx={17} cy={19} r={3.5} />
    <path d="M7 34l10-9 8 7 6-5 10 8" />
  </svg>
);
const IcoPerson: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 48 48" fill={c}>
    <circle cx={24} cy={17} r={9} />
    <path d="M6 46c0-10 8-16 18-16s18 6 18 16z" />
  </svg>
);
const IcoCheck: React.FC<{ s: number; c: string; p?: number }> = ({ s, c, p = 1 }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={3.2} strokeLinecap="round" strokeLinejoin="round">
    <path d="M5 12.5l4.5 4.5L19 7.5" strokeDasharray={22} strokeDashoffset={22 * (1 - p)} />
  </svg>
);
const IcoSpark: React.FC<{ s: number; c: string }> = ({ s, c }) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill={c}>
    <path d="M10 2.5l1.9 5.6 5.6 1.9-5.600 1.900L10 17.500l-1.900-5.600L2.500 10l5.600-1.900z" />
    <path d="M18.500 14l.900 2.600 2.600.900-2.600.900-.900 2.600-.900-2.600-2.600-.900 2.600-.900z" />
  </svg>
);
const WaGlyph: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 48 48">
    <path d="M24 9a15 15 0 0 0-12.800 22.800L9 39l7.500-2.100A15 15 0 1 0 24 9z" fill="#FFFFFF" />
    <path d="M19 16.500c-.400-.800-.800-.800-1.100-.800h-1c-.400 0-.900.100-1.400.700-.500.500-1.800 1.700-1.800 4.200s1.800 4.900 2.100 5.300c.200.300 3.500 5.600 8.700 7.600 4.300 1.700 5.200 1.400 6.100 1.300.900-.100 3-1.200 3.400-2.400.400-1.200.400-2.200.300-2.400-.100-.200-.400-.300-1-.600l-3.400-1.600c-.500-.200-.800-.200-1.100.200-.400.500-1.300 1.600-1.600 2-.300.300-.600.400-1.100.100-.500-.200-2.100-.800-4.100-2.500-1.500-1.300-2.500-3-2.800-3.500-.300-.500 0-.800.200-1 .200-.200.500-.600.800-.900.200-.300.300-.500.500-.800.200-.400.100-.700-.100-.900z" fill={WA} />
  </svg>
);

// foto do ensaio num cartão de canto redondo, inteira (o cartão tem a proporção da foto)
const Photo: React.FC<{ id: string; w: number; r?: number; zoom?: number; style?: React.CSSProperties }> = ({ id, w, r = 44, zoom = 1, style }) => (
  <div style={{ width: w, height: w / ar(id), borderRadius: r, overflow: "hidden", boxShadow: "0 40px 90px rgba(0,0,0,0.28)", flexShrink: 0, ...style }}>
    <Img src={staticFile(`ensaio/${id}.jpg`)} style={{ width: "100%", height: "100%", objectFit: "cover", transform: `scale(${zoom.toFixed(4)})` }} />
  </div>
);

// ───────── cena 1 · gancho (preto) ─────────
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const A_OUT = 1.72;
  const days = [3, 2, 1];
  const flips = [0.3, 0.78, 1.22];
  const idx = t < flips[1] ? 0 : t < flips[2] ? 1 : 2;
  const roll = k(t, flips[idx], 0.28);
  const cardIn = pop(t, 0.08, 0.55);
  const cardOut = lin(t, A_OUT, A_OUT + 0.25);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {/* A · o calendário contando os dias */}
      {t < A_OUT + 0.3 ? (
        <>
          <div style={{ position: "absolute", left: 540 - 380, top: 520 - 150, width: 760, height: 760, borderRadius: "50%", background: "radial-gradient(circle, rgba(235,169,140,0.30) 0%, rgba(235,169,140,0) 62%)", opacity: cardIn * (1 - cardOut) }} />
          <div style={{ position: "absolute", left: 540 - 190, top: 420 + Math.sin(t * 2.2) * 8, width: 380, height: 420, borderRadius: 70, background: CARD_D, border: "1.5px solid rgba(255,255,255,0.09)", overflow: "hidden", opacity: Math.min(1, cardIn * 2) * (1 - cardOut), transform: `translateY(${((1 - cardIn) * 260).toFixed(1)}px) scale(${((0.45 + 0.55 * cardIn - 0.14 * cardOut) * (1 + 0.08 * (1 - k(t, flips[idx], 0.32)))).toFixed(3)})`, filter: `blur(${((1 - Math.min(1, cardIn)) * 14 + cardOut * 14).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", left: 0, right: 0, top: 44, textAlign: "center", fontFamily: F, fontWeight: 700, fontSize: 30, letterSpacing: "0.2em", ...grad(ROSE_D) }}>{days[idx] === 1 ? "FALTA" : "FALTAM"}</div>
            <div style={{ position: "absolute", left: 0, right: 0, top: 84, height: 230, overflow: "hidden" }}>
              <div style={{ textAlign: "center", fontFamily: F, fontWeight: 700, fontSize: 220, lineHeight: "230px", letterSpacing: "-0.05em", color: "#FFFFFF", transform: `translateY(${((1 - roll) * 150).toFixed(1)}px)`, opacity: roll, filter: `blur(${((1 - roll) * 10).toFixed(1)}px)` }}>{days[idx]}</div>
            </div>
            <div style={{ position: "absolute", left: 0, right: 0, top: 322, textAlign: "center", fontFamily: F, fontWeight: 500, fontSize: 40, color: "rgba(255,255,255,0.6)", letterSpacing: "-0.01em" }}>{days[idx] === 1 ? "dia" : "dias"}</div>
          </div>
          <Lines t={t} top={1000} size={104} color="#FFFFFF" accent={ROSE_D} out={A_OUT} items={[["Seu aniversário", 0.28], ["tá chegando", 0.96, true]]} />
        </>
      ) : null}
      {/* B · a galeria vazia */}
      {t >= A_OUT ? (
        <>
          <div style={{ position: "absolute", left: 0, right: 0, top: 268, display: "flex", justifyContent: "center" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 14, padding: "14px 30px", borderRadius: 999, background: CARD_D, border: "1.5px solid rgba(255,255,255,0.09)", fontFamily: F, fontWeight: 600, fontSize: 34, color: "rgba(255,255,255,0.72)", letterSpacing: "-0.01em", opacity: k(t, 3.1, 0.3), transform: `scale(${(0.8 + 0.2 * pop(t, 3.1, 0.4)).toFixed(3)})` }}>
              <IcoImage s={38} c="rgba(255,255,255,0.72)" />
              <span>0 fotos</span>
            </div>
          </div>
          <div style={{ position: "absolute", left: 111, top: 372, width: 858, display: "flex", flexWrap: "wrap", gap: 24, transform: `scale(${(1 + 0.045 * lin(t, 1.98, T2)).toFixed(4)})` }}>
            {[0, 1, 2, 3, 4, 5].map((i) => {
              const at = 1.98 + i * 0.11;
              const e = pop(t, at, 0.5);
              const sweep = ((t * 0.55 + i * 0.13) % 1.6) / 1.6;
              const hop = t >= 2.75 && t < 4.3 ? [0, 4, 2, 3, 1, 5][Math.floor((t - 2.75) / 0.19) % 6] : -1;
              const on = hop === i;
              return (
                <div key={i} style={{ position: "relative", width: 270, height: 330, borderRadius: 38, background: on ? "#232326" : "#111113", border: on ? "3px solid rgba(255,255,255,0.9)" : "2px dashed rgba(255,255,255,0.17)", boxSizing: "border-box", overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `translateY(${((1 - e) * 70 + Math.sin(t * 1.8 + i * 1.1) * 5).toFixed(1)}px) scale(${(0.85 + 0.15 * e + (on ? 0.05 : 0)).toFixed(3)})` }}>
                  <IcoImage s={84} c={on ? "rgba(255,255,255,0.6)" : "rgba(255,255,255,0.20)"} />
                  <div style={{ position: "absolute", top: 0, bottom: 0, width: 150, left: -150 + sweep * 570, background: "linear-gradient(100deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.06) 50%, rgba(255,255,255,0) 100%)" }} />
                </div>
              );
            })}
          </div>
          <Lines t={t} top={1150} size={82} color="#FFFFFF" accent={ROSE_D} items={[["E você ainda não tem", 1.94], ["fotos que dão vontade", 3.25], ["de postar?", 4.3, true]]} />
          <div style={{ position: "absolute", left: 0, right: 0, top: 1490, display: "flex", justifyContent: "center" }}>
            <div style={{ width: 350, height: 108, borderRadius: 54, background: CARD_D, border: "1.5px solid rgba(255,255,255,0.09)", display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 600, fontSize: 44, letterSpacing: "-0.02em", color: "rgba(255,255,255,0.34)", opacity: k(t, 4.34, 0.2), transform: `translateX(${(Math.sin((t - 4.56) * 42) * 16 * (t > 4.56 ? Math.max(0, 1 - (t - 4.56) / 0.45) : 0)).toFixed(1)}px) scale(${(0.7 + 0.3 * pop(t, 4.34, 0.4)).toFixed(3)})` }}>Postar</div>
          </div>
        </>
      ) : null}
    </AbsoluteFill>
  );
};

// ───────── cena 2 · a dor (claro) ─────────
const Dor: React.FC<{ t: number }> = ({ t }) => {
  const items: [string, number][] = [["Ensaio", 5.6], ["Cenário", 5.95], ["Produção", 6.3], ["Sessão completa", 6.65]];
  const hand = t * 360 * 1.4;
  return (
    <AbsoluteFill style={{ background: LIGHT }}>
      <Lines t={t} top={390} size={88} color={INK} accent={ROSE_L} items={[["Nem sempre dá tempo", 5.47], ["de organizar um", 6.5], ["ensaio completo.", 7.05, true]]} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 760, display: "flex", justifyContent: "center" }}>
        <div style={{ display: "flex", alignItems: "center", gap: 16, padding: "16px 32px 16px 22px", borderRadius: 999, background: "#FFFFFF", boxShadow: SHADOW, opacity: k(t, 6.15, 0.3), transform: `scale(${(0.8 + 0.2 * pop(t, 6.15, 0.4)).toFixed(3)})` }}>
          <svg width={50} height={50} viewBox="0 0 48 48" fill="none" stroke={INK} strokeWidth={3.4} strokeLinecap="round">
            <circle cx={24} cy={24} r={18} />
            <path d="M24 24V13" transform={`rotate(${hand.toFixed(1)} 24 24)`} />
            <path d="M24 24h7" transform={`rotate(${(hand / 12).toFixed(1)} 24 24)`} />
          </svg>
          <span style={{ fontFamily: F, fontWeight: 600, fontSize: 36, color: INK, letterSpacing: "-0.02em" }}>Falta tempo</span>
        </div>
      </div>
      {items.map(([label, at], i) => {
        const e = pop(t, at, 0.5);
        return (
          <div key={i} style={{ position: "absolute", left: 100, top: 910 + i * 166, width: 880, height: 142, borderRadius: 38, background: "#FFFFFF", boxShadow: SHADOW, display: "flex", alignItems: "center", gap: 30, padding: "0 40px", boxSizing: "border-box", opacity: Math.min(1, e * 2), transform: `translate(${(34 * Math.sin(Math.PI * lin(t, 7.1 + i * 0.13, 7.42 + i * 0.13))).toFixed(1)}px, ${((1 - e) * 120 + Math.sin(t * 2 + i * 1.3) * 4).toFixed(1)}px) rotate(${((1 - e) * (i % 2 ? 3 : -3)).toFixed(2)}deg)` }}>
            <div style={{ width: 54, height: 54, borderRadius: "50%", border: "3.5px solid #C7C7CC", boxSizing: "border-box", flexShrink: 0 }} />
            <span style={{ fontFamily: F, fontWeight: 600, fontSize: 50, color: INK, letterSpacing: "-0.03em" }}>{label}</span>
            <div style={{ flex: 1 }} />
            <div style={{ display: "flex", gap: 8 }}>{[0, 1, 2].map((d) => <div key={d} style={{ width: 10, height: 10, borderRadius: 5, background: "#C7C7CC", opacity: 0.35 + 0.65 * Math.max(0, Math.sin(t * 6 - d * 0.9 - i)) }} />)}</div>
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ───────── cena 3 · a transformação (claro) ─────────
const Cria: React.FC<{ t: number }> = ({ t }) => {
  const B = 9.68, C = 12.22;
  const cardIn = pop(t, 8.3, 0.55);
  const exit = lin(t, C - 0.08, C + 0.2);
  const press = interpolate(t, [10.3, 10.4, 10.62], [0, 1, 0], cl);
  const prog = interpolate(t, [10.45, 11.4], [0, 1], { ...cl, easing: INOUT });
  const done = t >= 11.45;
  const making = t >= 10.42 && !done;
  const reveal = k(t, C + 0.08, 0.7);
  const pills: [string, number, number, number][] = [["Cenário", 13.0, 62, 820], ["Estética", 13.3, 742, 1150], ["Produção", 13.6, 82, 1490]];
  return (
    <AbsoluteFill style={{ background: LIGHT }}>
      {t < B + 0.3 ? <Lines t={t} top={440} size={100} color={INK} accent={ROSE_L} out={B - 0.06} items={[["Com algumas", 8.39], ["fotos suas,", 8.92, true]]} /> : null}
      {t >= B && t < C + 0.3 ? <Lines t={t} top={400} size={80} color={INK} accent={ROSE_L} out={C - 0.1} items={[["A gente cria um ensaio", 9.78], ["de aniversário", 10.72], ["personalizado", 11.48, true]]} /> : null}
      {t >= C ? <Lines t={t} top={250} size={96} color={INK} accent={ROSE_L} items={[["com IA,", 12.34, true], ["pensado pra você.", 13.0]]} /> : null}

      {/* o cartão que recebe as fotos e o botão */}
      {t < C + 0.25 ? (
        <>
          <div style={{ position: "absolute", left: 140, top: 850 + Math.sin(t * 1.9) * 6, width: 800, height: 470, borderRadius: 58, background: "#FFFFFF", boxShadow: SHADOW, opacity: Math.min(1, cardIn * 2) * (1 - exit), transform: `scale(${(0.82 + 0.18 * cardIn - 0.12 * exit + (making ? 0.018 * Math.sin((t - 10.42) * 13) : 0)).toFixed(3)})`, filter: `blur(${(exit * 14).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", left: 50, right: 50, top: 40, display: "flex", justifyContent: "space-between", alignItems: "center", fontFamily: F, fontWeight: 600, fontSize: 36, letterSpacing: "-0.02em" }}>
              <span style={{ color: INK }}>Suas fotos</span>
              <span style={{ color: GRAY }}>{t < 8.5 ? 0 : t < 8.8 ? 1 : t < 9.1 ? 2 : 3} de 3</span>
            </div>
            {[0, 1, 2].map((i) => {
              const at = 8.5 + i * 0.3;
              const e = pop(t, at, 0.45);
              const sw = making ? ((t - 10.42) * 1.5 + i * 0.2) % 1 : -1;
              return (
                <div key={i} style={{ position: "absolute", left: 50 + i * 244, top: 124, width: 212, height: 296, borderRadius: 30, background: "linear-gradient(180deg, #EDEDF0 0%, #DCDCE1 100%)", overflow: "hidden", display: "flex", alignItems: "flex-end", justifyContent: "center", opacity: Math.min(1, e * 2), transform: `scale(${(0.6 + 0.4 * e).toFixed(3)})` }}>
                  <IcoPerson s={176} c="#BDBDC4" />
                  {sw >= 0 ? <div style={{ position: "absolute", top: 0, bottom: 0, width: 130, left: -130 + sw * 470, background: "linear-gradient(100deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.85) 50%, rgba(255,255,255,0) 100%)" }} /> : null}
                  <div style={{ position: "absolute", right: 14, top: 14, width: 46, height: 46, borderRadius: 23, background: INK, display: "flex", alignItems: "center", justifyContent: "center", transform: `scale(${pop(t, at + 0.14, 0.35).toFixed(3)})` }}>
                    <IcoCheck s={28} c="#FFFFFF" p={lin(t, at + 0.16, at + 0.36)} />
                  </div>
                </div>
              );
            })}
          </div>
          <div style={{ position: "absolute", left: 250, top: 1420, width: 580, height: 136, borderRadius: 68, background: INK, overflow: "hidden", display: "flex", alignItems: "center", justifyContent: "center", gap: 18, boxShadow: "0 24px 50px rgba(0,0,0,0.22)", opacity: k(t, 9.85, 0.25) * (1 - exit), transform: `scale(${((0.7 + 0.3 * pop(t, 9.85, 0.45)) * (1 - 0.07 * press) - 0.12 * exit).toFixed(3)})`, filter: `blur(${(exit * 14).toFixed(1)}px)` }}>
            <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: `${(prog * 100).toFixed(1)}%`, backgroundImage: ROSE_L, backgroundSize: "580px 100%", opacity: t >= 10.42 ? 1 : 0 }} />
            <div style={{ position: "relative", display: "flex", alignItems: "center", gap: 18 }}>
              {done ? <IcoCheck s={50} c="#FFFFFF" p={lin(t, 11.45, 11.7)} /> : <div style={{ transform: `rotate(${(making ? t * 220 : 0).toFixed(1)}deg)`, display: "flex" }}><IcoSpark s={50} c="#FFFFFF" /></div>}
