            </div>
          </div>
        </>
      ) : null}

      {t >= 10.42 && t < C ? [...Array(11)].map((_, i) => {
        const s0 = 10.46 + i * 0.1;
        const u = lin(t, s0, s0 + 0.75);
        if (u <= 0 || u >= 1) return null;
        const tx = 190 + ((i * 263) % 700), ty = 900 + ((i * 131) % 330);
        const e = Easing.out(Easing.cubic)(u);
        return (
          <div key={i} style={{ position: "absolute", left: 540 + (tx - 540) * e - 30, top: 1488 + (ty - 1488) * e - 30, opacity: Math.sin(Math.PI * u), transform: `scale(${(0.5 + 0.9 * Math.sin(Math.PI * u)).toFixed(2)}) rotate(${(u * 160).toFixed(0)}deg)` }}>
            <IcoSpark s={60} c={["#D98C7A", "#C96F8A", "#E0A97E"][i % 3]} />
