      }) : null}

      {/* o ensaio pronto */}
      {t >= C ? (
        <>
          <div style={{ position: "absolute", left: 150, top: 540, opacity: Math.min(1, reveal * 1.8), transform: `scale(${(0.8 + 0.2 * reveal).toFixed(3)})`, filter: `blur(${((1 - reveal) * 22).toFixed(1)}px)` }}>
