            <div style={{ position: "absolute", inset: 0, borderRadius: 52, overflow: "hidden" }}>
              <div style={{ position: "absolute", top: -100, bottom: -100, width: 260, left: -300 + lin(t, C + 0.25, C + 1.05) * 1400, transform: "rotate(14deg)", background: "linear-gradient(90deg, rgba(255,255,255,0) 0%, rgba(255,255,255,0.55) 50%, rgba(255,255,255,0) 100%)" }} />
            </div>
          </div>
          {pills.map(([label, at, x, y], i) => {
            const e = pop(t, at, 0.45);
            return (
              <div key={i} style={{ position: "absolute", left: x, top: y + Math.sin(t * 2.1 + i * 2) * 7, display: "flex", alignItems: "center", gap: 14, padding: "20px 34px 20px 26px", borderRadius: 999, background: "#FFFFFF", boxShadow: "0 22px 50px rgba(0,0,0,0.20)", opacity: Math.min(1, e * 2), transform: `scale(${(0.5 + 0.5 * e).toFixed(3)})` }}>
                <div style={{ width: 20, height: 20, borderRadius: 10, backgroundImage: ROSE_L }} />
                <span style={{ fontFamily: F, fontWeight: 600, fontSize: 42, color: INK, letterSpacing: "-0.03em" }}>{label}</span>
              </div>
            );
          })}
        </>
      ) : null}
    </AbsoluteFill>
  );
};

// ───────── cena 4 · a prova (preto): vitrine dos ensaios, um por batida ─────────
const SHOW = ["p03", "p12", "p07", "p09", "p04"];
const Prova: React.FC<{ t: number }> = ({ t }) => {
  const BOX_W = 900, BOX_H = 1330, CY = 1010;
  const cur = Math.min(SHOW.length - 1, Math.floor((t - SHOW0) / BEAT));
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {t < SHOW0 + 0.2 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 770, display: "flex", flexDirection: "column", alignItems: "center", transform: `scale(${(1 + 0.12 * lin(t, SHOW0 - 0.2, SHOW0 + 0.1)).toFixed(3)})` }}>
          {([["Olha a", 14.59], ["diferença!", 14.81, true]] as L[]).map(([w, at, hl], i) => (
            <div key={i} style={{ fontFamily: F, fontWeight: 700, fontSize: 168, lineHeight: 1.06, letterSpacing: "-0.045em", whiteSpace: "nowrap", color: "#FFFFFF", paddingBottom: 10, ...(hl ? grad(ROSE_D) : {}), ...blurIn(t, at, SHOW0 - 0.16, 0.4) }}>{w}</div>
          ))}
        </div>
      ) : null}
      {t >= SHOW0 - 0.05 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 150, textAlign: "center", fontFamily: F, fontWeight: 600, fontSize: 44, letterSpacing: "-0.02em", color: "rgba(255,255,255,0.62)", ...blurIn(t, SHOW0, undefined, 0.4) }}>Olha a diferença</div>
      ) : null}
      {SHOW.map((id, i) => {
        const at = SHOW0 + i * BEAT;
        if (t < at - 0.02 || t > at + BEAT + 0.3) return null;
        const a = ar(id);
        const w = Math.min(BOX_W, BOX_H * a);
        const h = w / a;
        const e = k(t, at, 0.34);
        const o = i < SHOW.length - 1 ? lin(t, at + BEAT, at + BEAT + 0.24) : 0;
        const from = [`translateX(${(1 - e) * 760}px) rotate(${(1 - e) * 9}deg)`, `scale(${0.55 + 0.45 * e})`, `translateY(${(1 - e) * 900}px)`, `translateX(${-(1 - e) * 760}px) rotate(${-(1 - e) * 9}deg)`, `scale(${1.45 - 0.45 * e})`][i];
        return (
          <div key={id} style={{ position: "absolute", left: 540 - w / 2, top: CY - h / 2, opacity: Math.min(1, e * 2.5) * (1 - o), transform: `${from} scale(${(1 - 0.1 * o).toFixed(3)})`, filter: `blur(${((1 - e) * 10 + o * 8).toFixed(1)}px)`, zIndex: i }}>
            <Photo id={id} w={w} r={50} zoom={1 + 0.06 * lin(t, at, at + BEAT + 0.3)} />
          </div>
        );
      })}
      {t >= SHOW0 ? (
        <div style={{ position: "absolute", left: 0, right: 0, top: 1752, display: "flex", justifyContent: "center", gap: 14, opacity: k(t, SHOW0, 0.3) }}>
          {SHOW.map((_, i) => <div key={i} style={{ height: 14, borderRadius: 7, width: i === cur ? 44 : 14, background: i === cur ? "#FFFFFF" : "rgba(255,255,255,0.3)" }} />)}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

