          <div style={{ fontFamily: F, fontWeight: 600, fontSize: 45, lineHeight: 1.12, color: INK, letterSpacing: "-0.03em", whiteSpace: "nowrap", ...blurIn(t, 23.06, undefined, 0.4) }}>ganham um brinde especial</div>
        </div>
      </div>
      {/* confete do brinde: uma vez só, em "brinde especial" */}
      {t >= 23.42 && t < 25.2 ? [...Array(18)].map((_, i) => {
