        return <div key={i} style={{ position: "absolute", left: px, top: py, width: 16, height: i % 3 ? 16 : 26, borderRadius: i % 2 ? 8 : 3, background: ["#E0A07E", "#D98BA0", "#F2CBA8", "#C96F6A"][i % 4], opacity: 1 - lin(u, 0.9, 1.6), transform: `rotate(${(u * (300 + i * 40)).toFixed(0)}deg)` }} />;
