export const EnsaioAniversario: React.FC = () => {
  const t = interpolate(useCurrentFrame() / ENS_FPS, WARP.map((p) => p[0]), WARP.map((p) => p[1]), cl);
  // trocas de cena, cada uma de um jeito: folha que sobe · empurrão lateral · íris · obturador
  const sheet = interpolate(t, [T2 - 0.3, T2 + 0.25], [0, 1], { ...cl, easing: OUT });
  const push = interpolate(t, [T3 - 0.28, T3 + 0.22], [0, 1], { ...cl, easing: INOUT });
  const iris = interpolate(t, [T4 - 0.22, T4 + 0.26], [0, 1], { ...cl, easing: INOUT });
  const shut = interpolate(t, [T5 - 0.22, T5 + 0.2], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      {t < T2 + 0.3 ? (
        <AbsoluteFill style={{ transform: `scale(${(1 - 0.07 * sheet).toFixed(4)})`, opacity: 1 - 0.5 * sheet }}>
          <Hook t={t} />
        </AbsoluteFill>
      ) : null}
      {t >= T2 - 0.32 && t < T3 + 0.25 ? (
        <AbsoluteFill style={{ transform: `translateY(${((1 - sheet) * 1920).toFixed(1)}px) translateX(${(-push * 1080).toFixed(1)}px)`, borderRadius: `${((1 - sheet) * 90).toFixed(0)}px ${((1 - sheet) * 90).toFixed(0)}px 0 0`, overflow: "hidden" }}>
          <Dor t={t} />
        </AbsoluteFill>
      ) : null}
      {t >= T3 - 0.3 && t < T4 + 0.3 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1080).toFixed(1)}px)` }}>
          <Cria t={t} />
        </AbsoluteFill>
      ) : null}
      {t >= T5 - 0.25 ? <Cta t={t} /> : null}
      {t >= T4 - 0.24 && t < T5 + 0.22 ? (
        <AbsoluteFill style={{ clipPath: t < T4 + 0.3 ? `circle(${(iris * 2300).toFixed(0)}px at 540px 1010px)` : `inset(${(shut * 50).toFixed(2)}% 0 ${(shut * 50).toFixed(2)}% 0)` }}>
          <Prova t={t} />
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

